import 'dart:math' as math;

import 'package:sekka/Core/Helper/transport_type_helper.dart';

class CapacityPredictionModel {
  static const int maxSeats = 35;

  final String timestamp;
  final int carriageId;
  final int predictedCount;
  final double capacityPercent;
  final bool seatsAvailable;
  final bool isOffline;

  /// Fake seat data generated by [random].
  final int fakeSeatsAvailable;
  final double fakeCapacityPercent;

  CapacityPredictionModel({
    required this.timestamp,
    required this.carriageId,
    required this.predictedCount,
    required this.capacityPercent,
    required this.seatsAvailable,
    required this.isOffline,
    required this.fakeSeatsAvailable,
    required this.fakeCapacityPercent,
  });

  /// Generates a [CapacityPredictionModel] with randomised seat / capacity
  /// data. Seats are capped at [maxSeats] (35). The percentage is derived
  /// from how many seats are *taken* out of 35.
  factory CapacityPredictionModel.random({
    String timestamp = '',
    int carriageId = 0,
    int predictedCount = 0,
    double capacityPercent = 0.0,
    bool seatsAvailable = true,
    bool isOffline = false,
  }) {
    final rng = math.Random();
    // seats available = random number from 0 to maxSeats
    final fakeSeats = rng.nextInt(maxSeats + 1); // 0..35
    // occupied seats
    final occupied = maxSeats - fakeSeats;
    final fakePct = (occupied / maxSeats) * 100;

    return CapacityPredictionModel(
      timestamp: timestamp,
      carriageId: carriageId,
      predictedCount: predictedCount,
      capacityPercent: capacityPercent,
      seatsAvailable: seatsAvailable,
      isOffline: isOffline,
      fakeSeatsAvailable: fakeSeats,
      fakeCapacityPercent: fakePct,
    );
  }

  factory CapacityPredictionModel.fromJson(Map<String, dynamic> json) {
    final rng = math.Random();
    final fakeSeats = rng.nextInt(maxSeats + 1);
    final occupied = maxSeats - fakeSeats;
    final fakePct = (occupied / maxSeats) * 100;

    return CapacityPredictionModel(
      timestamp: json['timestamp'] as String? ?? '',
      carriageId: (json['carriage_id'] as num?)?.toInt() ?? 0,
      predictedCount: (json['predicted_count'] as num?)?.toInt() ?? 0,
      capacityPercent: (json['capacity_percent'] as num?)?.toDouble() ?? 0.0,
      seatsAvailable: (json['seats_available'] as String?)?.toUpperCase() == 'YES',
      isOffline: json['is_offline'] as bool? ?? false,
      fakeSeatsAvailable: fakeSeats,
      fakeCapacityPercent: fakePct,
    );
  }

  CrowdingLevel get crowdingLevel {
    if (capacityPercent < 40) return CrowdingLevel.low;
    if (capacityPercent < 70) return CrowdingLevel.medium;
    return CrowdingLevel.high;
  }

  /// Crowding level based on the *fake* percentage (seats taken out of 35).
  CrowdingLevel get fakeCrowdingLevel {
    if (fakeCapacityPercent < 40) return CrowdingLevel.low;
    if (fakeCapacityPercent < 70) return CrowdingLevel.medium;
    return CrowdingLevel.high;
  }
}
